132	      "content step-type record must form a stacking context (isolation: isolate " +
133	      "or an explicit z-index) so the z-index:-1 lane underlay paints above the " +
134	      "ancestor pane's opaque var(--bg) background instead of being hidden behind it");
135	  });
136	
137	  // The intervening panes really do carry an opaque background — this is the
138	  // ancestor that would hide an un-contained underlay. Lock it so the test
139	  // above keeps its rationale: if these ever become transparent the stacking
140	  // requirement could be relaxed, but today it is mandatory.
141	  check("G2 intervening panes carry an opaque var(--bg) background", () => {
142	    const detailPane = ruleBody(CSS, ".history-detail-pane");
143	    assert.ok(/background:\s*var\(--bg\)/.test(detailPane),
144	      ".history-detail-pane must carry the opaque var(--bg) background the underlay must paint above");
145	  });
146	
147	  // ---- (c) boundary / container-edge suppression ---------------------------
148	  // The base ::before underlay rule carries
149	  // `[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)`,
150	  // giving it specificity (0,5,1). The four boundary-suppression rules below
151	  // must WIN the cascade over it to reset the ±7px overflow at step/container
152	  // edges. Two things make them win and BOTH must be locked, or the reset can
153	  // silently regress (a single-`.history-detail` selector is only (0,3,1), so
154	  // its top:0/bottom:0 would lose to the base ::before and the lane would bleed
155	  // across the .history-step-header into the neighbouring step):
156	  //   1. equal-or-greater specificity — achieved by tripling `.history-detail`
157	  //      (`.history-detail.history-detail.history-detail …`) to reach (0,5,1);
158	  //   2. later source order than the base ::before rule, to win the tie.
159	  // The single-`.history-detail` substring is found inside the tripled selector
160	  // regardless, so the needles below carry the full tripled prefix and we also
161	  // assert each rule appears AFTER the base ::before rule in source order.
162	  const TRIPLE = ".history-detail.history-detail.history-detail";
163	  const baseBeforeSel =
164	    `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before`;
165	  const baseBeforeAt = CSS.indexOf(baseBeforeSel);
166	  assert.notEqual(baseBeforeAt, -1, "base ::before underlay rule must exist");
167	
168	  function boundaryRule(needle, edge) {
169	    // Must use the tripled prefix (specificity (0,5,1) >= base (0,5,1)).
170	    const at = CSS.indexOf(needle);
171	    assert.notEqual(
172	      at, -1,
173	      `boundary rule must use the specificity-tripled prefix: ${needle}`);
174	    // Must come AFTER the base ::before rule so it wins the specificity tie.
175	    assert.ok(
176	      at > baseBeforeAt,
177	      `boundary rule must appear later in source order than the base ::before ` +
178	      `rule to win the cascade tie: ${needle}`);
179	    const body = ruleBody(CSS, needle);
180	    assert.ok(
181	      new RegExp(`${edge}:\\s*0`).test(body),
182	      `boundary rule must reset ${edge} to 0: ${needle}`);
183	  }
184	
185	  check("G2 step first block does not overflow upward across the header", () => {
186	    boundaryRule(`${TRIPLE} .history-step-header + .conv-record::before`, "top");
187	  });
188	  check("G2 step last block does not overflow downward across the next header", () => {
189	    boundaryRule(`${TRIPLE} .conv-record:has(+ .history-step-header)::before`, "bottom");
190	  });
191	  check("G2 container first/last child does not overflow past the edge", () => {
192	    boundaryRule(`${TRIPLE} > .conv-record:first-child::before`, "top");
193	    boundaryRule(`${TRIPLE} > .conv-record:last-child::before`, "bottom");
194	  });
195	
196	  // Pin that the tripling is load-bearing: a single-`.history-detail` boundary
197	  // selector (specificity (0,3,1)) would LOSE the cascade to the base ::before
198	  // rule (0,5,1). Assert the boundary rules do NOT degrade to a bare
199	  // single-`.history-detail` form, so a future edit dropping the tripling fails.
200	  check("G2 boundary rules keep the load-bearing specificity tripling", () => {
201	    // Strip /* ... */ comments first: the explanatory comment above the rules
202	    // deliberately quotes the single-`.history-detail` anti-pattern as an
203	    // example, which would otherwise trip the "must be tripled" scan below.
204	    const CSS_NC = CSS.replace(/\/\*[\s\S]*?\*\//g, "");
205	    for (const needle of [
206	      " .history-step-header + .conv-record::before",
207	      " .conv-record:has(+ .history-step-header)::before",
208	      " > .conv-record:first-child::before",
209	      " > .conv-record:last-child::before",
210	    ]) {
211	      // Every occurrence of this boundary tail must be preceded by the tripled
212	      // prefix — never a bare single `.history-detail`.
213	      let from = 0;
214	      let found = false;
215	      for (;;) {
216	        const at = CSS_NC.indexOf(needle, from);
217	        if (at === -1) break;
218	        found = true;
219	        const before = CSS_NC.slice(0, at);
220	        assert.ok(
221	          before.endsWith(TRIPLE),
222	          `boundary rule '${needle.trim()}' must be prefixed by the tripled ` +
223	          `'${TRIPLE}' (specificity (0,5,1)); a single '.history-detail' ` +
224	          `(0,3,1) would lose the cascade to the base ::before underlay`);
225	        from = at + needle.length;
226	      }
227	      assert.ok(found, `boundary rule tail must exist: ${needle.trim()}`);
228	    }
229	  });
230	
231	  // ---- (d) status / DAG markers stay excluded ------------------------------
232	  check("G2 lane geometry still excludes status / group markers", () => {
233	    // Both the position:relative base rule and the ::before rule must carry the
234	    // :not(.step-status-row):not(.group-status-marker) exclusion.
235	    const baseSel =
236	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`;
237	    const beforeSel =
238	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before`;
239	    assert.notEqual(CSS.indexOf(baseSel), -1,
240	      "base geometry rule must exclude .step-status-row/.group-status-marker");
241	    assert.notEqual(CSS.indexOf(beforeSel), -1,
242	      "::before geometry rule must exclude .step-status-row/.group-status-marker");
243	  });
244	}
