5602	// Ensure the floating step header is mounted on `scroller` (as its first child,
5603	// so the sticky anchor pins to the scroll viewport top), wire the scroll
5604	// listener once, refresh the cached header offsets from the freshly-rendered
5605	// `content`, and update the float. Idempotent — safe to call after every render
5606	// (a full rebuild wipes the float via innerHTML="", so re-inserting the same
5607	// detached node re-mounts it without disturbing fold/raw/chip state on bubbles).
5608	function ensureStickyHeaderMounted(scroller, content) {
5609	  if (!scroller || !content) return;
5610	  let floatEl = scroller.__convStickyFloat;
5611	  if (!floatEl) {
5612	    floatEl = buildStickyHeaderEl(scroller);
5613	    scroller.__convStickyFloat = floatEl;
